    20  struct backtrace_location {
    21    int32_t lineno;
    22    mrb_sym method_id;
    23    const char *filename;
    24  };
    25
    26  typedef void (*each_backtrace_func)(mrb_state*, const struct backtrace_location*, void*);
    27
    28  static const mrb_data_type bt_type = { "Backtrace", mrb_free };
    29
    30  struct RObject *mrb_unpack_backtrace(mrb_state *mrb, struct RObject *backtrace);
