    96  static void
    97  print_backtrace(mrb_state *mrb, struct RObject *exc, struct RArray *backtrace)
    98  {
    99    mrb_int i;
   100    mrb_int n = (backtrace ? ARY_LEN(backtrace) : 0);
   101    mrb_value *loc, mesg;
   102
   103    if (n != 0) {
   104      if (n > 1) {
   105        fputs("trace (most recent call last):\n", stderr);
   106      }
   107      for (i=n-1,loc=&ARY_PTR(backtrace)[i]; i>0; i--,loc--) {
   108        if (mrb_string_p(*loc)) {
   109          fprintf(stderr, "\t[%d] ", (int)i);
   110          fwrite(RSTRING_PTR(*loc), (int)RSTRING_LEN(*loc), 1, stderr);
   111          fputc('\n', stderr);
   112        }
   113      }
   114      if (mrb_string_p(*loc)) {
   115        fwrite(RSTRING_PTR(*loc), (int)RSTRING_LEN(*loc), 1, stderr);
   116        fputs(": ", stderr);
   117      }
   118    }
   119    else {
   120      fputs("(unknown):0: ", stderr);
   121    }
   122
   123    if (exc == mrb->nomem_err) {
   124      static const char nomem[] = "Out of memory (NoMemoryError)\n";
   125      fwrite(nomem, sizeof(nomem)-1, 1, stderr);
   126    }
   127    else {
   128      mesg = mrb_exc_inspect(mrb, mrb_obj_value(exc));
   129      fwrite(RSTRING_PTR(mesg), RSTRING_LEN(mesg), 1, stderr);
   130      fputc('\n', stderr);
   131    }
   132  }
