   139  MRB_API void
   140  mrb_print_backtrace(mrb_state *mrb)
   141  {
   142    if (!mrb->exc || mrb->exc->tt != MRB_TT_EXCEPTION) {
   143      return;
   144    }
   145
   146    struct RObject *backtrace = ((struct RException*)mrb->exc)->backtrace;
   147    if (backtrace && backtrace->tt != MRB_TT_ARRAY) backtrace = mrb_unpack_backtrace(mrb, backtrace);
   148    print_backtrace(mrb, mrb->exc, (struct RArray*)backtrace);
   149  }
