   159  static void
   160  count_backtrace_i(mrb_state *mrb,
   161                   const struct backtrace_location *loc,
   162                   void *data)
   163  {
   164    int *lenp = (int*)data;
   165
   166    (*lenp)++;
   167  }
   168
   169  static void
   170  pack_backtrace_i(mrb_state *mrb,
   171                   const struct backtrace_location *loc,
   172                   void *data)
   173  {
   174    struct backtrace_location **pptr = (struct backtrace_location**)data;
   175    struct backtrace_location *ptr = *pptr;
   176
   177    *ptr = *loc;
   178    *pptr = ptr+1;
   179  }
