   200  static void
   201  store_backtrace(mrb_state *mrb, mrb_value exc, struct RObject *backtrace)
   202  {
   203    struct RException *e = mrb_exc_ptr(exc);
   204    e->backtrace = backtrace;
   205    mrb_field_write_barrier(mrb, (struct RBasic*)e, (struct RBasic*)backtrace);
   206  }
