   208  void
   209  mrb_keep_backtrace(mrb_state *mrb, mrb_value exc)
   210  {
   211    int ai;
   212
   213    if (mrb_exc_ptr(exc)->backtrace) return;
   214    ai = mrb_gc_arena_save(mrb);
   215    struct RObject *backtrace = packed_backtrace(mrb);
   216    store_backtrace(mrb, exc, backtrace);
   217    mrb_gc_arena_restore(mrb, ai);
   218  }
