   260  mrb_exc_backtrace(mrb_state *mrb, mrb_value exc)
   130   *
   131   * Returns this exception's file name, line number,
   132   * message and class name.
   133   * If file name or line number is not set,
   134   * returns message and class name.
   135   */
   136
   137  mrb_value
   138  mrb_exc_inspect(mrb_state *mrb, mrb_value exc)
   139  {
   140    mrb_value cname = mrb_mod_to_s(mrb, mrb_obj_value(mrb_obj_class(mrb, exc)));
   141    mrb_value mesg = mrb_exc_mesg_get(mrb, mrb_exc_ptr(exc)); /* string or nil */
   142    return (mrb_nil_p(mesg)||RSTRING_LEN(mesg)==0) ? cname : mrb_format(mrb, "%v (%v)", mesg, cname);
   143  }
