   147  static void
   148  set_backtrace(mrb_state *mrb, mrb_value exc, mrb_value backtrace)
   149  {
   150    if (!mrb_array_p(backtrace)) {
   151    type_err:
   152      mrb_raise(mrb, E_TYPE_ERROR, "backtrace must be Array of String");
   153    }
   154    else {
   155      const mrb_value *p = RARRAY_PTR(backtrace);
   156      const mrb_value *pend = p + RARRAY_LEN(backtrace);
   157
   158      while (p < pend) {
   159        if (!mrb_string_p(*p)) goto type_err;
   160        p++;
   161      }
   162    }
   163    mrb_exc_ptr(exc)->backtrace = mrb_obj_ptr(backtrace);
   164    mrb_field_write_barrier_value(mrb, mrb_basic_ptr(exc), backtrace);
   165  }
