   167  static mrb_value
   168  exc_set_backtrace(mrb_state *mrb, mrb_value exc)
   169  {
   170    mrb_value backtrace = mrb_get_arg1(mrb);
   171
   172    set_backtrace(mrb, exc, backtrace);
   173    return backtrace;
   174  }
