   176  void
   177  mrb_exc_set(mrb_state *mrb, mrb_value exc)
   178  {
   179    if (mrb_nil_p(exc)) {
   180      mrb->exc = 0;
   181    }
   182    else {
   183      mrb->exc = mrb_obj_ptr(exc);
   184      if (mrb->gc.arena_idx > 0 &&
   185          (struct RBasic*)mrb->exc == mrb->gc.arena[mrb->gc.arena_idx-1]) {
   186        mrb->gc.arena_idx--;
   187      }
   188      if (!mrb->gc.out_of_memory && !mrb_frozen_p(mrb->exc)) {
   189        mrb_keep_backtrace(mrb, exc);
   190      }
   191    }
   192  }
