   194  static mrb_noreturn void
   195  exc_throw(mrb_state *mrb, mrb_value exc)
   196  {
   197    if (!mrb->jmp) {
   198      mrb_print_error(mrb);
   199      abort();
   200    }
   201    MRB_THROW(mrb->jmp);
   202  }
   203
   204  MRB_API mrb_noreturn void
   205  mrb_exc_raise(mrb_state *mrb, mrb_value exc)
   206  {
   207    if (mrb_break_p(exc)) {
   208      mrb->exc = mrb_obj_ptr(exc);
   209    }
   210    else {
   211      if (mrb_type(exc) != MRB_TT_EXCEPTION) {
   212        mrb_raise(mrb, E_TYPE_ERROR, "exception object expected");
   213      }
   214      mrb_exc_set(mrb, exc);
   215    }
   216    exc_throw(mrb, exc);
   217  }
   218
   219  MRB_API mrb_noreturn void
   220  mrb_raise(mrb_state *mrb, struct RClass *c, const char *msg)
   221  {
   222    mrb_exc_raise(mrb, mrb_exc_new_str(mrb, c, mrb_str_new_cstr(mrb, msg)));
   223  }
